    "id": "camara-1317119-comissao-aprova-programa-para-",
    "title": "Comissão aprova programa para ampliar armazenagem agropecuária",
    "summary": "O projeto continua sendo discutido na Câmara dos Deputados.",
    "source": "Agência Câmara",
    "sourceUrl": "https://www.camara.leg.br",
    "articleUrl": "https://www.camara.leg.br/noticias/1317119-comissao-aprova-programa-para-ampliar-armazenagem-agropecuaria",
